<script lang="ts">
  import { onMount } from 'svelte';
  import { inView } from './autoplay';

  // K completions for one prompt. each is a rollout of cube tokens (varying length); the score is the
  // grader value, the advantage is relative to the group mean.
  const counts = [4, 6, 3, 5];
  const scores = [0.4, 0.9, 0.2, 0.6];
  const mean = scores.reduce((a, b) => a + b, 0) / scores.length;
  const maxCount = Math.max(...counts);

  const SCORE_AT = maxCount + 2;
  const JUDGE_AT = maxCount + 4;
  const PERIOD = maxCount + 11;

  let f = $state(0);
  let root: HTMLElement;

  let scored = $derived(f >= SCORE_AT);
  let judged = $derived(f >= JUDGE_AT);

  onMount(() => {
    let timer: ReturnType<typeof setInterval> | null = null;
    const start = () => {
      if (!timer) timer = setInterval(() => (f = f >= PERIOD ? 0 : f + 1), 180);
    };
    const stop = () => {
      if (timer) clearInterval(timer);
      timer = null;
    };
    const cleanup = inView(root, start, stop);
    return () => {
      stop();
      cleanup();
    };
  });
</script>

<div class="fig" bind:this={root}>
  <div class="grid">
    <span class="prompt">prompt</span>
    <div class="group">
      {#each counts as c, i}
        <div class="row">
          <div class="toks" class:up={judged && scores[i] >= mean} class:down={judged && scores[i] < mean}>
            {#each Array(c) as _, j}
              <span class="tok" class:on={f > j}></span>
            {/each}
          </div>
          <span class="score" class:on={scored}>{scores[i].toFixed(1)}</span>
        </div>
      {/each}
    </div>
  </div>

  <div class="caption">
    One prompt, several completions. Each is scored against the
    <span class="c-train">group average</span>: above-average completions are reinforced,
    below-average ones suppressed.
  </div>
</div>

