<script lang="ts">
  import { onMount } from 'svelte';
  import { inView } from './autoplay';

  // each lane is one GPU running the loop on its own slice. rollout token counts vary, so lanes finish
  // generating at different ticks (the straggler); they wait, then train (also varying), then meet at the
  // barrier for one synchronized optim across every lane. mirrors the hero conveyor in 2D.
  const CELL = 26;
  const GAP = 5;
  const PITCH = CELL + GAP;

  const roll = [5, 7, 4, 6]; // cells per lane: col 0 is the prompt, the rest are rollout tokens
  const train = [2, 3, 2, 3]; // training cells per lane (longer where the lane generated more)
  const maxRoll = Math.max(...roll);
  const maxTrain = Math.max(...train);
  const TOTAL = maxRoll + maxTrain;
  const LANES = roll.length;

  const laneW = TOTAL * CELL + (TOTAL - 1) * GAP;
  const syncX = maxRoll * PITCH - GAP / 2; // boundary where rollout ends, drawn as a faint divider
  const HOLD = 6;
  const PERIOD = TOTAL + HOLD;

  let f = $state(0);
  let root: HTMLElement;

  let optimLit = $derived(f >= TOTAL);

  onMount(() => {
    let timer: ReturnType<typeof setInterval> | null = null;
    const start = () => {
      if (!timer) timer = setInterval(() => (f = f >= PERIOD ? 0 : f + 1), 150);
    };
    const stop = () => {
      if (timer) clearInterval(timer);
      timer = null;
    };
    const cleanup = inView(root, start, stop);
    return () => {
      stop();
      cleanup();
    };
  });
</script>

<div class="fig" bind:this={root}>
  <div class="rig">
    <div class="housing">
      {#each Array(LANES) as _, i}
        <span class="gpu">GPU {i}</span>
      {/each}
    </div>

    <div class="track">
      <div class="lanes" style="width: {laneW}px">
        {#each roll as rc, i}
          <div class="lane" style="grid-template-columns: repeat({TOTAL}, {CELL}px); gap: {GAP}px">
            {#each Array(rc) as _, c}
              <span
                class="cell {c === 0 ? 'prompt' : 'roll'}"
                class:on={f > c}
                style="grid-column: {c + 1}"
              ></span>
            {/each}
            {#each Array(train[i]) as _, j}
              <span
                class="cell train"
                class:on={f >= maxRoll && f - maxRoll > j}
                style="grid-column: {maxRoll + j + 1}"
              ></span>
            {/each}
          </div>
        {/each}
        <span class="divider" style="left: {syncX}px"></span>
      </div>

      <div class="barrier"><span class="sync">sync</span></div>

      <span class="optim" class:lit={optimLit}>optim</span>
    </div>
  </div>

  <div class="caption">
    Each GPU runs the loop on its own slice of the batch. The copies finish at different times, wait at
    the <span class="c-optim">barrier</span>, then a single synchronized update is applied to every copy.
    This is data parallelism.
  </div>
</div>

