<script lang="ts">
  import { onMount } from 'svelte';
  import { inView } from './autoplay';

  const H = 32;
  const GAP = 6;

  let areaW = $state(0);
  let scored = $state(false);
  let root: HTMLElement;

  // square rollout tokens that fill the measured width, matching the rollout figure
  let n = $derived(Math.max(1, Math.floor((areaW + GAP) / (H + GAP))));
  let tokenW = $derived(n > 0 ? (areaW - (n - 1) * GAP) / n : H);

  onMount(() => {
    let timer: ReturnType<typeof setInterval> | null = null;
    const start = () => {
      if (!timer) timer = setInterval(() => (scored = !scored), 1500);
    };
    const stop = () => {
      if (timer) clearInterval(timer);
      timer = null;
    };
    const cleanup = inView(root, start, stop);
    return () => {
      stop();
      cleanup();
    };
  });
</script>

<div class="fig" bind:this={root}>
  <div class="lane">
    <span class="prompt">prompt</span>
    <div class="tokens" bind:clientWidth={areaW}>
      {#each Array(n) as _, i}
        <span class="tok" style="width: {tokenW}px; height: {H}px"></span>
      {/each}
    </div>
    <div class="train-wrap">
      <span class="score" class:on={scored}>reward</span>
      <span class="train" class:lit={scored}>train</span>
    </div>
    <span class="optim dim">optim</span>
  </div>

  <div class="caption">
    A <span class="c-train">grader</span> scores the completion. The score becomes a gradient that
    nudges the model toward higher-scoring completions. This is the
    <span class="c-train">train</span> step.
  </div>
</div>

