<script lang="ts">
  import { onMount } from 'svelte';
  import { inView } from './autoplay';

  // one engine holds the whole loop on the same GPUs. a gentle breathing glow marks it as live and
  // resident, the opposite of the split figure's recurring handoff.
  let lit = $state(false);
  let root: HTMLElement;

  onMount(() => {
    let timer: ReturnType<typeof setInterval> | null = null;
    const start = () => {
      lit = true;
      if (!timer) timer = setInterval(() => (lit = !lit), 1900);
    };
    const stop = () => {
      if (timer) clearInterval(timer);
      timer = null;
    };
    const cleanup = inView(root, start, stop);
    return () => {
      stop();
      cleanup();
    };
  });
</script>

<div class="fig" bind:this={root}>
  <div class="stage">
    <div class="tool" class:lit>
      <span class="tag">Harmony</span>
      <div class="blocks">
        <span class="prompt">prompt</span>
        <span class="roll"></span>
        <span class="train">train</span>
        <span class="optim">optim</span>
      </div>
    </div>
  </div>

  <div class="caption">
    Harmony runs the whole loop as one engine, on the same GPUs. No handoff, no second stack.
  </div>
</div>

