// run a callback only while the element is on screen. each figure drives its own animation with a
// setInterval; this just gates it so loops don't burn cycles when scrolled out of view.
export function inView(el: Element, onEnter: () => void, onLeave: () => void) {
  const io = new IntersectionObserver(
    (entries) => {
      for (const e of entries) (e.isIntersecting ? onEnter : onLeave)();
    },
    { threshold: 0.25 }
  );
  io.observe(el);
  return () => io.disconnect();
}
