<script lang="ts">
  import { onMount } from 'svelte';
  import { inView } from './autoplay';

  // same lane as rollout/train: prompt, rollout tokens, train, optim. the optim step sends the gradient
  // backward across the whole step (right to left). each block lifts and flashes the optim color as the
  // gradient passes: energy flowing back through the run, built from the established blocks.
  const H = 32;
  const GAP = 6;
  const IDLE = 4;
  const HOLD = 6;

  let areaW = $state(0);
  let f = $state(0);
  let root: HTMLElement;

  let n = $derived(Math.max(1, Math.floor((areaW + GAP) / (H + GAP))));
  let tokenW = $derived(n > 0 ? (areaW - (n - 1) * GAP) / n : H);
  let M = $derived(n + 3); // prompt + n tokens + train + optim
  let period = $derived(IDLE + M + HOLD);

  let sweeping = $derived(f >= IDLE && f < IDLE + M);
  let grad = $derived(sweeping ? M - 1 - (f - IDLE) : -1); // block index the gradient sits on

  const at = (idx: number) => grad === idx;

  onMount(() => {
    let timer: ReturnType<typeof setInterval> | null = null;
    const start = () => {
      if (!timer) timer = setInterval(() => (f = f >= period - 1 ? 0 : f + 1), 150);
    };
    const stop = () => {
      if (timer) clearInterval(timer);
      timer = null;
    };
    const cleanup = inView(root, start, stop);
    return () => {
      stop();
      cleanup();
    };
  });
</script>

<div class="fig" bind:this={root}>
  <div class="head">
    <span class="dir" class:show={sweeping}>&larr;&ensp;gradient</span>
  </div>

  <div class="lane">
    <span class="b prompt" class:at={at(0)}>prompt</span>
    <div class="tokens" bind:clientWidth={areaW}>
      {#each Array(n) as _, i}
        <span class="b tok" class:at={at(i + 1)} style="width: {tokenW}px; height: {H}px"></span>
      {/each}
    </div>
    <span class="b train" class:at={at(n + 1)}>train</span>
    <span class="b optim" class:at={at(n + 2)}>optim</span>
  </div>

  <div class="caption">
    The optimizer sends the gradient backward across the step, nudging every weight. The next step's
    rollouts come from a slightly better model. This <span class="c-optim">optim</span> step closes the
    loop.
  </div>
</div>

