import { mount } from 'svelte';
import Walkthrough from './figures/Walkthrough.svelte';
import Rollout from './figures/Rollout.svelte';
import Train from './figures/Train.svelte';
import Optim from './figures/Optim.svelte';
import Group from './figures/Group.svelte';
import Parallel from './figures/Parallel.svelte';
import Split from './figures/Split.svelte';
import Unified from './figures/Unified.svelte';
import Code from './figures/Code.svelte';

const figures: Record<string, any> = {
  walkthrough: Walkthrough,
  rollout: Rollout,
  train: Train,
  optim: Optim,
  group: Group,
  parallel: Parallel,
  split: Split,
  unified: Unified,
  code: Code,
};

function mountFigures() {
  document.querySelectorAll<HTMLElement>('[data-figure]').forEach((el) => {
    const name = el.dataset.figure;
    if (!name) return;
    const Component = figures[name];
    if (!Component) return;
    mount(Component, { target: el });
  });
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', mountFigures);
} else {
  mountFigures();
}
