<script lang="ts">
  import { onMount } from 'svelte';
  import { inView } from './autoplay';

  const H = 32;
  const GAP = 6;
  const HOLD = 7; // ticks the full row holds before resetting

  let areaW = $state(0);
  let f = $state(0);
  let root: HTMLElement;

  // square tokens that fill the measured width: floor() guarantees each token is at least H wide.
  let n = $derived(Math.max(1, Math.floor((areaW + GAP) / (H + GAP))));
  let tokenW = $derived(n > 0 ? (areaW - (n - 1) * GAP) / n : H);
  let gen = $derived(Math.min(f, n));

  onMount(() => {
    let timer: ReturnType<typeof setInterval> | null = null;
    const start = () => {
      if (timer) return;
      timer = setInterval(() => {
        f = f > n + HOLD ? 0 : f + 1;
      }, 170);
    };
    const stop = () => {
      if (timer) clearInterval(timer);
      timer = null;
    };
    const cleanup = inView(root, start, stop);
    return () => {
      stop();
      cleanup();
    };
  });
</script>

<div class="fig" bind:this={root}>
  <div class="lane">
    <span class="prompt">prompt</span>
    <div class="tokens" bind:clientWidth={areaW}>
      {#each Array(n) as _, i}
        <span class="tok" class:on={i < gen} style="width: {tokenW}px; height: {H}px"></span>
      {/each}
    </div>
  </div>

  <div class="caption">
    The model reads a <span class="c-prompt">prompt</span> and generates a
    <span class="c-rollout">completion</span>, one token at a time. This is the
    <span class="c-rollout">rollout</span>.
  </div>
</div>

