<script lang="ts">
  import { onMount } from 'svelte';
  import { inView } from './autoplay';

  // two separate stacks: an inference engine runs rollout, a training framework runs train/optim. the
  // weight transfer between them fires every step, so it pulses to mark the recurring cost.
  let shipping = $state(false);
  let root: HTMLElement;

  onMount(() => {
    let timer: ReturnType<typeof setInterval> | null = null;
    const start = () => {
      if (!timer) timer = setInterval(() => (shipping = !shipping), 1100);
    };
    const stop = () => {
      if (timer) clearInterval(timer);
      timer = null;
    };
    const cleanup = inView(root, start, stop);
    return () => {
      stop();
      cleanup();
    };
  });
</script>

<div class="fig" bind:this={root}>
  <div class="stage">
    <div class="pair">
      <div class="tool">
        <span class="tag">inference engine</span>
        <div class="blocks">
          <span class="prompt">prompt</span>
          <span class="roll"></span>
        </div>
      </div>
      <div class="handoff" class:ship={shipping}>
        <span class="handoff-label">weight<br />transfer</span>
      </div>
      <div class="tool">
        <span class="tag">training framework</span>
        <div class="blocks">
          <span class="train">train</span>
          <span class="optim">optim</span>
        </div>
      </div>
    </div>
  </div>

  <div class="caption">
    <span class="c-rollout">Rollout</span> runs on an inference engine.
    <span class="c-train">Train</span> and <span class="c-optim">optim</span> run on a separate training
    framework. The trained weights have to cross the boundary between them.
  </div>
</div>

