<script lang="ts">
  import { onMount } from 'svelte';

  let step = $state(0);
  let ready = $state(false);
  // the demo iframe lives in the static HTML (so the Webflow inline step rewrites its src to the absolute
  // assets URL); the walkthrough only drives it by posting config. it never creates the iframe.
  let iframe: HTMLIFrameElement | null = null;

  onMount(() => {
    iframe = document.querySelector('iframe.loop-demo');
    if (!iframe) return;
    const onload = () => (ready = true);
    iframe.addEventListener('load', onload);
    try {
      if (iframe.contentWindow?.document.readyState === 'complete') ready = true;
    } catch {}
    return () => iframe?.removeEventListener('load', onload);
  });

  const steps = [
    {
      lanes: 1,
      batch: 1,
      title: 'One step',
      lead: `Each step runs three phases in sequence: <span class="c-rollout">rollout</span>, <span class="c-train">train</span>, <span class="c-optim">optim</span>. Generate, score, update.`,
    },
    {
      lanes: 1,
      batch: 8,
      title: 'A batch',
      lead: `A real step covers many prompts at once. Here, eight <span class="c-rollout">roll out</span> before a single <span class="c-train">train</span> and <span class="c-optim">optim</span>.`,
    },
    {
      lanes: 4,
      batch: 32,
      title: 'Parallel training',
      lead: `Split the batch across GPUs and the loops run in parallel. They finish at different times, then meet at the barrier to sync.`,
    },
  ];

  function apply() {
    if (!ready || !iframe?.contentWindow) return;
    const { lanes, batch } = steps[step];
    iframe.contentWindow.postMessage({ source: 'harmony-walkthrough', lanes, batch }, '*');
  }

  $effect(() => {
    apply();
  });

  const prev = () => {
    if (step > 0) step--;
  };
  const next = () => {
    if (step < steps.length - 1) step++;
  };
</script>

<div class="ctrl">
  <div class="info">
    <span class="kicker">{steps[step].title}</span>
    <div class="lead">{@html steps[step].lead}</div>
  </div>

  <div class="nav">
    <button class="arrow" onclick={prev} disabled={step === 0} aria-label="Previous" type="button">←</button>
    <div class="dots">
      {#each steps as _, i}
        <button
          class="dot"
          class:active={i === step}
          onclick={() => (step = i)}
          aria-label={`Step ${i + 1}`}
          type="button"
        ></button>
      {/each}
    </div>
    <button class="arrow" onclick={next} disabled={step === steps.length - 1} aria-label="Next" type="button">→</button>
  </div>
</div>

