<script lang="ts">
  // the real Harmony recipe: one engine, the whole GRPO loop in one file. lines are color-coded by
  // phase. c: n=neutral r=rollout t=train o=optim x=comment
  type Line = { t: string; c: string; cm?: string };

  const recipe: Line[] = [
    { t: 'policy    = await config.model.spawn_train("policy", ctx, tp=4)', c: 'n', cm: '  # one engine' },
    { t: 'reference = await policy.clone_inf()', c: 'n' },
    { t: '', c: 'n' },
    { t: 'for prompt in dataset:', c: 'n' },
    { t: '    samples = await async_map(policy.generate_tokens, [prompt] * 8)', c: 'r' },
    { t: '    texts   = await async_map(policy.detokenize_thread, samples)', c: 'r' },
    { t: '    grades  = await async_map(grader.grade, texts)', c: 't' },
    { t: '    scores  = np.array([g.value for g in grades])', c: 't' },
    { t: '    adv     = (scores - scores.mean()) / (scores.std() + 1e-8)', c: 't' },
    { t: '    for sample, a in zip(samples, adv):', c: 't' },
    { t: '        lp     = await policy.logprobs_per_token(sample)', c: 't' },
    { t: '        ref_lp = await reference.logprobs_per_token(sample)', c: 't' },
    { t: '        await policy.train_grpo(sample, lp, ref_lp, [a] * len(lp))', c: 't' },
    { t: '    await policy.optim_step(config.learning_rate)', c: 'o' },
  ];

  const cap =
    'The whole loop, one engine: <span class="c-rollout">generate</span>, <span class="c-train">train</span>, <span class="c-optim">optim</span>, with nothing to sync between them.';
</script>

<div class="codeblock">
  {#each recipe as line}
    <div class="codeline"><span class="cl-{line.c}">{line.t || ' '}</span>{#if line.cm}<span class="cl-x">{line.cm}</span>{/if}</div>
  {/each}
</div>
<div class="codecap">{@html cap}</div>
